      { icone: "🧅", titre: "Beaucoup d'oignons", detail: "Comptez TROIS fois plus d'oignons que de viande en poids. C'est contre-intuitif mais c'est la recette.", badge: null },
      { icone: "🔪", titre: "Émincer fin", detail: "Émincez-les finement à la mandoline : ils doivent fondre complètement, pas rester en lamelles.", badge: null },
      { icone: "🥩", titre: "Saisir", detail: "Colorez le morceau de bœuf sur toutes ses faces dans l'huile d'olive, puis ajoutez carotte et céleri.", badge: null },
      { icone: "🏔️", titre: "La montagne", detail: "Recouvrez la viande de TOUS les oignons : cela paraît absurde, ils vont réduire de quatre cinquièmes.", badge: null },
      { icone: "♨️", titre: "Trois heures", detail: "Couvrez et laissez à tout petit feu 3 heures, en remuant toutes les 30 minutes. Les oignons rendent leur eau puis confisent.", badge: null },
      { icone: "🍷", titre: "Déglacer", detail: "Vin blanc quand les oignons commencent à accrocher et à dorer — cela décolle les sucs et relance la fondue.", badge: null },
      { icone: "🍝", titre: "Finir", detail: "1 heure de plus à découvert jusqu'à une crème brune. Effilochez la viande dedans, pecorino râpé à table.", badge: null }
